import org.rabochaya.projects.*;import java.util.*;import java.io.*;import org.w3c.dom.*;import javax.xml.parsers.*;import javax.xml.transform.*;import javax.xml.transform.dom.DOMSource;import javax.xml.transform.stream.StreamResult;
public final class ObjectClipboardTests {
 static int checks;static void check(boolean ok){checks++;if(!ok)throw new AssertionError("check "+checks);}
 static Element parse(String xml)throws Exception{DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);return f.newDocumentBuilder().parse(new ByteArrayInputStream(xml.getBytes("UTF-8"))).getDocumentElement();}
 static String xml(Element e)throws Exception{StringWriter w=new StringWriter();TransformerFactory.newInstance().newTransformer().transform(new DOMSource(e),new StreamResult(w));return w.toString();}
 static void bad(Element root,Runnable action)throws Exception{String before=xml(root);boolean no=false;try{action.run();}catch(IllegalArgumentException|IllegalStateException e){no=true;}check(no);check(xml(root).equals(before));}
 static void badClip(byte[] bytes){boolean no=false;try{ObjectClipboard.decode(bytes);}catch(IOException e){no=true;}check(no);}
 public static void main(String[] args)throws Exception{
  Element root=parse("<Document xmlns='http://www.opengis.net/kml/2.2'><Style id='shared'/><Folder id='folder'><name>Folder</name><x:opaque xmlns:x='urn:extra'>keep opaque</x:opaque><Style id='inside'><LineStyle><color>ff00ff00</color></LineStyle></Style><Schema id='schema'/><Placemark id='one'><name>One</name><description><![CDATA[<a href='#one'>self</a> <a href='#two'>other</a> <img src='attachments/keep.jpg'/> #one plain]]></description><styleUrl>#inside</styleUrl><ExtendedData><SchemaData schemaUrl='#schema'/></ExtendedData><LineString id='line'><altitudeMode>absolute</altitudeMode><coordinates>1,2,123 3,4,-7</coordinates></LineString></Placemark><Placemark id='two'><name>Two</name><styleUrl>#shared</styleUrl><Point><coordinates>5,6,8</coordinates></Point></Placemark></Folder><Folder><name>Destination</name></Folder></Document>");
  Element source=ObjectTree.resolve(root,"0"),target=ObjectTree.resolve(root,"1");String before=xml(source),token=ObjectTree.token(root);check(ObjectTree.selection(root,Arrays.asList("0/0","0"),token).equals(Arrays.asList("0")));check(ObjectTree.copy(root,Arrays.asList("0","0/0"),"1",token)==1);check(xml(source).equals(before));
  Element clone=ObjectTree.resolve(root,"1/0");check(!clone.getAttribute("id").equals("folder"));check(clone.getElementsByTagNameNS("urn:extra","opaque").item(0).getTextContent().equals("keep opaque"));NodeList nodes=clone.getElementsByTagNameNS("*","*");Map<String,Element> names=new HashMap<>();Set<String> ids=new HashSet<>();ids.add(clone.getAttribute("id"));for(int i=0;i<nodes.getLength();i++){Element e=(Element)nodes.item(i);String id=e.getAttribute("id");if(!id.isEmpty())check(ids.add(id)&&!Arrays.asList("folder","inside","schema","one","line","two","shared").contains(id));if(e.getLocalName().equals("Placemark"))names.put(e.getElementsByTagNameNS("*","name").item(0).getTextContent(),e);}
  Element one=names.get("One"),two=names.get("Two");String style=((Element)clone.getElementsByTagNameNS("*","Style").item(0)).getAttribute("id"),schema=((Element)clone.getElementsByTagNameNS("*","Schema").item(0)).getAttribute("id");check(one.getElementsByTagNameNS("*","styleUrl").item(0).getTextContent().equals("#"+style));check(((Element)one.getElementsByTagNameNS("*","SchemaData").item(0)).getAttribute("schemaUrl").equals("#"+schema));check(two.getElementsByTagNameNS("*","styleUrl").item(0).getTextContent().equals("#shared"));String description=one.getElementsByTagNameNS("*","description").item(0).getTextContent();check(description.contains("href='#"+one.getAttribute("id")+"'")&&description.contains("href='#"+two.getAttribute("id")+"'"));check(description.contains("attachments/keep.jpg")&&description.contains("#one plain"));check(one.getElementsByTagNameNS("*","coordinates").item(0).getTextContent().equals("1,2,123 3,4,-7"));check(one.getElementsByTagNameNS("*","altitudeMode").item(0).getTextContent().equals("absolute"));
  String newToken=ObjectTree.token(root);bad(root,()->ObjectTree.copy(root,Arrays.asList("0"),"0",newToken));bad(root,()->ObjectTree.copy(root,Arrays.asList("0"),"0/0",newToken));bad(root,()->ObjectTree.copy(root,Arrays.asList("0/0","9"),"1",newToken));bad(root,()->ObjectTree.copy(root,Arrays.asList("0"),"1",token));
  check(ObjectTree.copy(root,Arrays.asList("0/0","0/1"),"1",newToken)==2);check(xml(source).equals(before));check(ObjectTree.rows(root).size()==9);
  Element dup=parse("<Document><Folder id='duplicate'/><Placemark id='duplicate'/></Document>");bad(dup,()->ObjectTree.copy(dup,Arrays.asList("0"),"",ObjectTree.token(dup)));
  Element extension=parse("<Document><Folder xmlns:x='urn:extra'><x:opaque id='custom'/></Folder></Document>");bad(extension,()->ObjectTree.copy(extension,Arrays.asList("0"),"",ObjectTree.token(extension)));
  Element qualified=parse("<Document><Folder xml:id='x'/></Document>");bad(qualified,()->ObjectTree.copy(qualified,Arrays.asList("0"),"",ObjectTree.token(qualified)));
  Element external=parse("<Document xmlns='http://www.opengis.net/kml/2.2'><Placemark id='p'><styleUrl>https://invalid.example/style.kml#p</styleUrl><description><![CDATA[<a href='https://invalid.example/#p'>external</a>]]></description></Placemark></Document>");ObjectTree.copy(external,Arrays.asList("0"),"",ObjectTree.token(external));Element ec=ObjectTree.resolve(external,"1");check(ec.getElementsByTagNameNS("*","styleUrl").item(0).getTextContent().equals("https://invalid.example/style.kml#p"));check(ec.getElementsByTagNameNS("*","description").item(0).getTextContent().contains("https://invalid.example/#p"));
  ObjectClipboard clip=new ObjectClipboard(7,true,ObjectTree.token(root),Arrays.asList("0","1/0"));byte[] encoded=clip.encode();ObjectClipboard restored=ObjectClipboard.decode(encoded);check(restored.project==7&&restored.cut&&restored.keys.equals(clip.keys)&&restored.token.equals(clip.token));check(restored.fingerprint().equals(clip.fingerprint()));List<String> defensive=new ArrayList<>(Arrays.asList("0"));ObjectClipboard independent=new ObjectClipboard(1,false,clip.token,defensive);defensive.clear();check(independent.keys.size()==1);boolean immutable=false;try{independent.keys.add("1");}catch(UnsupportedOperationException e){immutable=true;}check(immutable);
  for(int i:new int[]{0,4,10,encoded.length/2,encoded.length-1}){byte[] broken=encoded.clone();broken[i]^=1;badClip(broken);}badClip(null);badClip(new byte[0]);badClip(Arrays.copyOf(encoded,encoded.length-1));badClip(new byte[ObjectClipboard.MAX_BYTES+1]);
  for(String key:new String[]{"","00","-1","1/","9999999999999999"}){boolean no=false;try{new ObjectClipboard(1,false,clip.token,Arrays.asList(key));}catch(IllegalArgumentException e){no=true;}check(no);}
  boolean invalid=false;try{new ObjectClipboard(0,false,clip.token,Arrays.asList("0"));}catch(IllegalArgumentException e){invalid=true;}check(invalid);
  System.out.println("PASS ObjectClipboard/Copy: "+checks+" assertions");
 }
}
